/// <summary>
/// SalesInvoiceLineV3Entity COC class
/// </summary>
[ExtensionOf(tableStr(SalesInvoiceLineV3Entity))]
final class METSalesInvoiceLineV3Entity_Extension
{
}

Method.Source:
    /// <summary>
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        next postLoad();

        changecompany(this.DataAreaId)
        {
            RefRecId productRecId = InventTable::itemProduct(this.METItemId);
            //MPJ_24809 Returns Claims
            SalesLine       metSalesLineStd, metSalesLineStdCalc;
            select firstonly METBrokenCaseForClaims from metSalesLineStd                
                where metSalesLineStd.InventTransIdReturn == this.METInventTransId;
            if(metSalesLineStd.METBrokenCaseForClaims)
            {
                while select metSalesLineStdCalc
                    where metSalesLineStdCalc.InventTransIdReturn == this.METInventTransId
                {
                
                    this.METCurrentClaimedQty   += UnitOfMeasureConverter::convert(metSalesLineStdCalc.SalesQty,
                                                   UnitOfMeasure::unitOfMeasureIdBySymbol(metSalesLineStdCalc.SalesUnit),
                        UnitOfMeasure::unitOfMeasureIdBySymbol(METCustParameters::Find().BrokenCaseReturnUnitOfMeasure),
                                                   NoYes::Yes, InventTable::itemProduct(metSalesLineStdCalc.ItemId), NoYes::Yes);
                }
                this.METBrokenCase  = true;
            }
            else
            {
                select sum(SalesQty) from metSalesLineStd
                    where metSalesLineStd.InventTransIdReturn == this.METInventTransId;
        
                this.METCurrentClaimedQty   = metSalesLineStd.SalesQty;
            }

            InventDim inventDim;
            ReqItemTable reqItemTable;
            CustInvoiceTrans custInvoiceTrans;
            METSalesLinePriceComponent metSalesLinePriceComponent;

            select sum(LineAmount) from custInvoiceTrans
                where custInvoiceTrans.InvoiceId == this.InvoiceNumber;

            // broken fees
            select sum(value) from metSalesLinePriceComponent
                where metSalesLinePriceComponent.Component == METConstants::brokenCaseFee
                && metSalesLinePriceComponent.InventTransId == this.METInventTransId;

            select firstonly VendId from reqItemTable
                where reqItemTable.ItemId == this.METItemId
                join inventDim
                    where inventDim.InventDimId == reqItemTable.CovInventDimId
                    && inventDim.InventSiteId == this.InventorySiteId;

            this.METInvoiceTotalAmount = custInvoiceTrans.LineAmount;
            this.METInvoiceBasePrice = this.SalesPrice - this.DiscAmount;
            this.METExtendedWholeSaleTotal = this.LineAmount + this.LineTotalTaxAmount;
            this.METLineGSTTotal = this.getMETGSTAmount();
            this.METLineWETTotal = this.getMETWETAmount();
            this.METLineWEGTotal = this.getMETWEGAmount();
            this.METBrokenCaseFee = metSalesLinePriceComponent.Value;
            this.METVendorAccountNumber = reqItemTable.VendId;
            this.METLevyType = this.getProductTextAttribueVal(productRecId, METConstants::LevyTypeAttributeId);
            this.METPricedByWeight = this.getProductBooleanAttributeVal(productRecId, METConstants::PricedByWeightAttributeId);
            this.METTaxRate = this.getTaxRate();
            this.METPackQuantity = this.getMETPackQauntity();
        }
		
    }

    /// <summary>
    /// MPJ_24809 Returns Claims
    /// </summary>
    /// <returns> barcode string value</returns>
    private static server str getSalesInvoiceLineGTIN()
    {
        str                 metBarcode;
        SysDictTable        metDictInventItemBarcode = new SysDictTable(tableNum(InventItemBarcode));
        str                 metItemId;
        str                 metUom;
        str                 metSqlQuery = 'SELECT TOP 1 %1 FROM %2 WHERE %2.%3 = %4 AND %2.%5 = %6';
              

        metItemId = SysComputedColumn::returnField(dataentityviewstr(SalesInvoiceLineV3Entity), dataEntityDataSourceStr(SalesInvoiceLineV3Entity, CustInvoiceTrans),
                        fieldStr(CustInvoiceTrans, ItemId));
        
        metUom = SysComputedColumn::returnField(dataentityviewstr(SalesInvoiceLineV3Entity), dataEntityDataSourceStr(SalesInvoiceLineV3Entity, CustInvoiceTrans),
                        fieldStr(CustInvoiceTrans, SalesUnit));
        
        metBarcode = strFmt(@metSqlQuery,
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, ItemBarCode), DbBackend::Sql),
                            metDictInventItemBarcode.name(DbBackend::Sql),
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, ItemId), DbBackend::Sql),
                            metItemId,
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, UnitId), DbBackend::Sql),
                            metUom);

        return metBarcode;
    }

    /// <summary>
    /// Get Sales Invoice Indicator
    /// Do modify the METInvoiceIndicator in the below query in case of any modifications to enum
    /// </summary>
    /// <returns>Indicator info</returns>
    private static str getSalesInvoiceIndicator()
    {
        str inventTransId = SysComputedColumn::returnField(tableStr(SalesInvoiceLineV3Entity),
                                                            tableStr(CustInvoiceTrans),
                                                            fieldStr(CustInvoiceTrans, InventTransId));

        //DictEnum dictEnum = new DictEnum(enumNum(METInvoiceIndicator));
        
        str salesLineInvIndicator = strFmt(@"SELECT LEFT(
                                                STUFF(
                                                    (
                                                        SELECT DISTINCT ',' + IndicatorValue
                                                        FROM
                                                        (
                                                            SELECT EV.NAME AS IndicatorValue
                                                            FROM METSALESINVOICEINDICATORVIEW M
                                                            JOIN ENUMIDTABLE EI
                                                                ON EI.NAME = 'METInvoiceIndicator'
                                                            JOIN ENUMVALUETABLE EV
                                                                ON EV.ENUMID = EI.ID
                                                               AND EV.ENUMVALUE = M.CimponentInvoiceIndicator
                                                            WHERE M.INVENTTRANSID = %1
                                                              AND EV.ENUMVALUE <> 0

                                                            UNION

                                                            SELECT MSL.Indicators AS IndicatorValue
                                                            FROM SALESLINE SL
                                                            JOIN METSALESLINE MSL
                                                                ON SL.RECID = MSL.SALESLINE
                                                            WHERE SL.INVENTTRANSID = %1
                                                              AND ISNULL(MSL.Indicators, '') <> ''
                                                        ) X
                                                        FOR XML PATH(''), TYPE
                                                    ).value('.', 'NVARCHAR(MAX)')
                                                , 1, 1, '')
                                            , 20)",
                                            inventTransId);

        return salesLineInvIndicator;


    }

    /// <summary>
    /// Method to return tax amount
    /// </summary>
    /// <param name = "_taxCode">Tax code (GST, WET)</param>
    /// <returns>Tax amount</returns>
    public TaxAmountCur calculateTaxAmount(TaxCode  _taxCode = '')
    {
        TaxAmountCur    taxAmount;

        changecompany(this.DataAreaId)
        {
            TaxTrans taxTransLineTax;
            
            select sum(SourceRegulateAmountCur) from taxTransLineTax
                where taxTransLineTax.SourceRecId == this.RecId 
                    && taxTransLineTax.SourceTableId == tableNum(CustInvoiceTrans) 
                    && taxTransLineTax.InventTransId == this.METInventTransId 
                    && taxTransLineTax.TaxOrigin != TaxOrigin::TaxReversed
                    && taxTransLineTax.TaxCode == _taxCode;

            taxAmount = -taxTransLineTax.SourceRegulateAmountCur;
        }

        return taxAmount;
    }

/// <summary>
/// Get GST amount
/// </summary>
/// <returns>GST amount</returns>
public TaxRegulationAmountCur getMETGSTAmount()
{
    return this.calculateTaxAmount(METConstants::taxGroupGST);
}

/// <summary>
/// Get WET amount
/// </summary>
/// <returns>WET amount</returns>
public TaxRegulationAmountCur getMETWETAmount()
{
    return this.calculateTaxAmount(METConstants::WET);
}

/// <summary>
/// Get WEG amount
/// </summary>
/// <returns>WEG amount</returns>
public TaxRegulationAmountCur getMETWEGAmount()
{
    return this.calculateTaxAmount(METConstants::WEG);
}

    /// <summary>
    /// Bu348309 CB372 - V7 + V8 - E-invoice is not performant and requires design changes
    /// </summary>
    /// <param name = "_product"></param>
    /// <param name = "_attibuteName"></param>
    /// <returns></returns>
    public str getProductTextAttribueVal(RefRecId _product, Name _attibuteName)
    {
        EcoResValue ecoResValue;
        EcoResAttribute ecoResAttribute;
        EcoResProductAttributeValue ecoResProductAttributeValue;
        
        select firstonly ecoResProductAttributeValue
            where ecoResProductAttributeValue.Product == _product
            join ecoResAttribute
                where ecoResAttribute.RecId == ecoResProductAttributeValue.Attribute
                && ecoResAttribute.Name == _attibuteName
            join ecoResValue
                where ecoResValue.RecId == ecoResProductAttributeValue.Value;

        return ecoResProductAttributeValue.RecId ? ecoResValue.value() : strMin();
    }

    /// <summary>
    /// Bu348309 CB372 - V7 + V8 - E-invoice is not performant and requires design changes
    /// </summary>
    /// <param name = "_product"></param>
    /// <param name = "_attibuteName"></param>
    /// <returns></returns>
    public AttributeValueBoolean getProductBooleanAttributeVal(RefRecId _product, Name _attibuteName)
    {
        EcoResValue ecoResValue;
        EcoResAttribute ecoResAttribute;
        EcoResBooleanValue ecoResBooleanValue;
        EcoResProductAttributeValue ecoResProductAttributeValue;
        
        select firstonly ecoResProductAttributeValue
            where ecoResProductAttributeValue.Product == _product
            join ecoResAttribute
                where ecoResAttribute.RecId == ecoResProductAttributeValue.Attribute
                && ecoResAttribute.Name == _attibuteName
            join ecoResValue
                where ecoResValue.RecId == ecoResProductAttributeValue.Value
            join ecoResBooleanValue
                where ecoResBooleanValue.RecId == ecoResValue.RecId;

        return ecoResBooleanValue.BooleanValue;
    }

    /// <summary>
    /// Bu348309 CB372 - V7 + V8 - E-invoice is not performant and requires design changes
    /// </summary>
    /// <returns></returns>
    public TaxValue getTaxRate()
    {
        TaxTable taxTable;
        TaxOnItem taxOnItem;
        TaxItemGroupHeading taxItemGroupHeading;

        select firstonly TaxCode from taxTable
                where taxTable.TaxCode == METConstants::taxGroupGST
                join taxOnItem
                    where taxOnItem.TaxCode == taxTable.TaxCode
                exists join taxItemGroupHeading
                    where taxItemGroupHeading.TaxItemGroup == taxOnItem.TaxItemGroup
                    && taxItemGroupHeading.TaxItemGroup == this.METSalesTaxItemGroupCode;

        if (taxTable.TaxCode)
        {
            this.METTaxRate = TaxData::percent(taxTable.TaxCode, this.InvoiceDate, 0);
        }
            
        return taxTable.showTaxValue();
    }

    /// <summary>
    /// Bu348309 CB372 - V7 + V8 - E-invoice is not performant and requires design changes
    /// </summary>
    /// <returns></returns>
    public UnitOfMeasureConversionFactor getMETPackQauntity()
    {
        #define.DefaultUnit('EA')
        UnitOfMeasureFromRecId  fromUnit,toUnit;
        UnitOfMeasureConversionFactor packQuantity;

        if (this.METSalesUnit != #DefaultUnit && !this.METPricedByWeight)
        {
            fromUnit    = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.METSalesUnit);
            toUnit      = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(#DefaultUnit);

            if (!fromUnit || !toUnit)
            {
                packQuantity = 0;
            }
            else if (fromUnit == toUnit)
            {
                packQuantity = 1;
            }
            else
            {
                packQuantity = UnitOfMeasureConversion::findByConversion(fromUnit,
                                    toUnit,
                                    EcoResProduct::findByProductNumber(this.METItemId).RecId).Factor;
            }
        }
        else
        {
            packQuantity = 1;
        }

        return packQuantity;

    }
